      "name": "Money.java",
      "code": "import java.util.Objects;\n\npublic final class Money implements Comparable<Money> {\n    private final long amount; // minor units (e.g. cents, pence, paise)\n    private final Currency currency;\n\n    public Money(long amount, Currency currency) {\n        if (amount < 0) {\n            throw new IllegalArgumentException(\"Amount cannot be negative: \" + amount);\n        }\n        this.amount = amount;\n        this.currency = Objects.requireNonNull(currency, \"currency cannot be null\");\n    }\n\n    public static Money of(long amount, Currency currency) {\n        return new Money(amount, currency);\n    }\n\n    public static Money zero(Currency currency) {\n        return new Money(0, currency);\n    }\n\n    public long amount() {\n        return amount;\n    }\n\n    public Currency currency() {\n        return currency;\n    }\n\n    public Money add(Money other) {\n        validateSameCurrency(other);\n        return new Money(this.amount + other.amount, this.currency);\n    }\n\n    public Money subtract(Money other) {\n        validateSameCurrency(other);\n        if (this.amount < other.amount) {\n            throw new IllegalStateException(\"Insufficient balance: \" + this.amount + \" < \" + other.amount);\n        }\n        return new Money(this.amount - other.amount, this.currency);\n    }\n\n    public boolean isGreaterThan(Money other) {\n        validateSameCurrency(other);\n        return this.amount > other.amount;\n    }\n\n    public boolean isGreaterThanOrEqual(Money other) {\n        validateSameCurrency(other);\n        return this.amount >= other.amount;\n    }\n\n    public boolean isZero() {\n        return this.amount == 0;\n    }\n\n    private void validateSameCurrency(Money other) {\n        Objects.requireNonNull(other, \"other money cannot be null\");\n        if (this.currency != other.currency) {\n            throw new IllegalArgumentException(\"Currency mismatch: \" + this.currency + \" vs \" + other.currency);\n        }\n    }\n\n    @Override\n    public int compareTo(Money other) {\n        validateSameCurrency(other);\n        return Long.compare(this.amount, other.amount);\n    }\n\n    @Override\n    public boolean equals(Object o) {\n        if (this == o) return true;\n        if (!(o instanceof Money money)) return false;\n        return amount == money.amount && currency == money.currency;\n    }\n\n    @Override\n    public int hashCode() {\n        return Objects.hash(amount, currency);\n    }\n\n    @Override\n    public String toString() {\n        long whole = amount / 100;\n        long cents = Math.abs(amount % 100);\n        return String.format(\"%d.%02d %s\", whole, cents, currency);\n    }\n}\n"
