      "code": "import java.util.Objects;\nimport java.util.concurrent.locks.ReentrantLock;\n\npublic final class Account {\n    private final String accountId;\n    private final String ownerId;\n    private final Currency currency;\n    private final AccountType type;\n    private long availableBalance; // minor units\n    private long heldBalance;      // minor units\n    private final ReentrantLock lock = new ReentrantLock(true); // fair lock\n\n    public Account(String accountId, String ownerId, Currency currency, AccountType type) {\n        this.accountId = Objects.requireNonNull(accountId, \"accountId cannot be null\");\n        this.ownerId = Objects.requireNonNull(ownerId, \"ownerId cannot be null\");\n        this.currency = Objects.requireNonNull(currency, \"currency cannot be null\");\n        this.type = Objects.requireNonNull(type, \"type cannot be null\");\n        this.availableBalance = 0;\n        this.heldBalance = 0;\n    }\n\n    public String accountId() { return accountId; }\n    public String ownerId() { return ownerId; }\n    public Currency currency() { return currency; }\n    public AccountType type() { return type; }\n    public ReentrantLock lock() { return lock; }\n\n    public long availableBalance() {\n        lock.lock();\n        try {\n            return availableBalance;\n        } finally {\n            lock.unlock();\n        }\n    }\n\n    public long heldBalance() {\n        lock.lock();\n        try {\n            return heldBalance;\n        } finally {\n            lock.unlock();\n        }\n    }\n\n    public long totalBalance() {\n        lock.lock();\n        try {\n            return availableBalance + heldBalance;\n        } finally {\n            lock.unlock();\n        }\n    }\n\n    public Money getAvailableMoney() {\n        return Money.of(availableBalance(), currency);\n    }\n\n    public Money getTotalMoney() {\n        return Money.of(totalBalance(), currency);\n    }\n\n    public void credit(long amount) {\n        if (!lock.isHeldByCurrentThread()) {\n            throw new IllegalStateException(\"Account lock must be held to credit\");\n        }\n        if (amount < 0) {\n            throw new IllegalArgumentException(\"Credit amount cannot be negative: \" + amount);\n        }\n        this.availableBalance += amount;\n    }\n\n    public void debit(long amount) {\n        if (!lock.isHeldByCurrentThread()) {\n            throw new IllegalStateException(\"Account lock must be held to debit\");\n        }\n        if (amount < 0) {\n            throw new IllegalArgumentException(\"Debit amount cannot be negative: \" + amount);\n        }\n        if (this.availableBalance < amount) {\n            throw new IllegalStateException(\"Insufficient funds in \" + accountId + \": available \" + availableBalance + \" < \" + amount);\n        }\n        this.availableBalance -= amount;\n    }\n\n    public void hold(long amount) {\n        if (!lock.isHeldByCurrentThread()) {\n            throw new IllegalStateException(\"Account lock must be held to create hold\");\n        }\n        if (amount <= 0) {\n            throw new IllegalArgumentException(\"Hold amount must be positive: \" + amount);\n        }\n        if (this.availableBalance < amount) {\n            throw new IllegalStateException(\"Insufficient funds to hold in \" + accountId + \": available \" + availableBalance + \" < \" + amount);\n        }\n        this.availableBalance -= amount;\n        this.heldBalance += amount;\n    }\n\n    public void releaseHold(long amount) {\n        if (!lock.isHeldByCurrentThread()) {\n            throw new IllegalStateException(\"Account lock must be held to release hold\");\n        }\n        if (amount <= 0) {\n            throw new IllegalArgumentException(\"Release amount must be positive: \" + amount);\n        }\n        if (this.heldBalance < amount) {\n            throw new IllegalStateException(\"Cannot release more than held in \" + accountId + \": held \" + heldBalance + \" < \" + amount);\n        }\n        this.heldBalance -= amount;\n        this.availableBalance += amount;\n    }\n\n    public void debitHeld(long amount) {\n        if (!lock.isHeldByCurrentThread()) {\n            throw new IllegalStateException(\"Account lock must be held to debit held balance\");\n        }\n        if (amount <= 0) {\n            throw new IllegalArgumentException(\"Debit held amount must be positive: \" + amount);\n        }\n        if (this.heldBalance < amount) {\n            throw new IllegalStateException(\"Cannot debit more than held in \" + accountId + \": held \" + heldBalance + \" < \" + amount);\n        }\n        this.heldBalance -= amount;\n    }\n}\n"
