      "code": "import java.time.Instant;\nimport java.util.Collections;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Objects;\n\npublic final class Transaction {\n    private final String transactionId;\n    private final String idempotencyKey;\n    private final TransactionType type;\n    private final List<LedgerEntry> entries;\n    private final Instant timestamp;\n    private final String description;\n\n    public Transaction(String transactionId, String idempotencyKey, TransactionType type, List<LedgerEntry> entries, Instant timestamp, String description) {\n        this.transactionId = Objects.requireNonNull(transactionId, \"transactionId cannot be null\");\n        this.idempotencyKey = Objects.requireNonNull(idempotencyKey, \"idempotencyKey cannot be null\");\n        this.type = Objects.requireNonNull(type, \"type cannot be null\");\n        this.entries = List.copyOf(Objects.requireNonNull(entries, \"entries cannot be null\"));\n        this.timestamp = Objects.requireNonNull(timestamp, \"timestamp cannot be null\");\n        this.description = description == null ? \"\" : description;\n\n        if (this.entries.isEmpty()) {\n            throw new IllegalArgumentException(\"Transaction must contain at least one pair of ledger entries\");\n        }\n        if (!isBalanced()) {\n            throw new IllegalStateException(\"Double-entry transaction \" + transactionId + \" is not balanced: debits != credits\");\n        }\n    }\n\n    public String transactionId() { return transactionId; }\n    public String idempotencyKey() { return idempotencyKey; }\n    public TransactionType type() { return type; }\n    public List<LedgerEntry> entries() { return Collections.unmodifiableList(entries); }\n    public Instant timestamp() { return timestamp; }\n    public String description() { return description; }\n\n    public boolean isBalanced() {\n        Map<Currency, Long> netPerCurrency = new HashMap<>();\n        for (LedgerEntry entry : entries) {\n            Currency curr = entry.amount().currency();\n            long delta = entry.type() == EntryType.DEBIT ? entry.amount().amount() : -entry.amount().amount();\n            netPerCurrency.put(curr, netPerCurrency.getOrDefault(curr, 0L) + delta);\n        }\n        for (long balance : netPerCurrency.values()) {\n            if (balance != 0) {\n                return false;\n            }\n        }\n        return true;\n    }\n}\n"
