      "code": "import java.util.Map;\nimport java.util.Objects;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic final class ExchangeRateService {\n    private final Map<String, Double> rates = new ConcurrentHashMap<>();\n\n    public ExchangeRateService() {\n        for (Currency c : Currency.values()) {\n            setRate(c, c, 1.0);\n        }\n    }\n\n    private String key(Currency from, Currency to) {\n        return from.name() + \"->\" + to.name();\n    }\n\n    public void setRate(Currency from, Currency to, double rate) {\n        if (rate <= 0) {\n            throw new IllegalArgumentException(\"Exchange rate must be positive: \" + rate);\n        }\n        rates.put(key(from, to), rate);\n        rates.put(key(to, from), 1.0 / rate);\n    }\n\n    public double getRate(Currency from, Currency to) {\n        if (from == to) return 1.0;\n        Double r = rates.get(key(from, to));\n        if (r == null) {\n            throw new IllegalArgumentException(\"No exchange rate registered from \" + from + \" to \" + to);\n        }\n        return r;\n    }\n\n    public Money convert(Money source, Currency targetCurrency) {\n        Objects.requireNonNull(source, \"source money cannot be null\");\n        Objects.requireNonNull(targetCurrency, \"targetCurrency cannot be null\");\n        if (source.currency() == targetCurrency) {\n            return source;\n        }\n        double rate = getRate(source.currency(), targetCurrency);\n        long targetAmount = Math.round(source.amount() * rate);\n        return Money.of(targetAmount, targetCurrency);\n    }\n}\n"
