      "code": "import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic final class LedgerRepository {\n    private final Map<String, Account> accounts = new ConcurrentHashMap<>();\n    private final Map<String, Transaction> transactions = new ConcurrentHashMap<>();\n    private final Map<String, List<LedgerEntry>> accountEntries = new ConcurrentHashMap<>();\n    private final Map<String, PaymentHold> holds = new ConcurrentHashMap<>();\n    private final Map<String, IdempotencyRecord> idempotencyRecords = new ConcurrentHashMap<>();\n\n    public void saveAccount(Account account) {\n        accounts.put(account.accountId(), account);\n    }\n\n    public Account getAccount(String accountId) {\n        return accounts.get(accountId);\n    }\n\n    public List<Account> allAccounts() {\n        return new ArrayList<>(accounts.values());\n    }\n\n    public void saveTransaction(Transaction tx) {\n        transactions.put(tx.transactionId(), tx);\n        for (LedgerEntry entry : tx.entries()) {\n            accountEntries.computeIfAbsent(entry.accountId(), k -> Collections.synchronizedList(new ArrayList<>()))\n                    .add(entry);\n        }\n    }\n\n    public Transaction getTransaction(String txId) {\n        return transactions.get(txId);\n    }\n\n    public List<Transaction> allTransactions() {\n        return new ArrayList<>(transactions.values());\n    }\n\n    public List<LedgerEntry> getEntriesForAccount(String accountId) {\n        List<LedgerEntry> list = accountEntries.get(accountId);\n        if (list == null) return Collections.emptyList();\n        synchronized (list) {\n            return new ArrayList<>(list);\n        }\n    }\n\n    public void saveHold(PaymentHold hold) {\n        holds.put(hold.holdId(), hold);\n    }\n\n    public PaymentHold getHold(String holdId) {\n        return holds.get(holdId);\n    }\n\n    public List<PaymentHold> allHolds() {\n        return new ArrayList<>(holds.values());\n    }\n\n    public IdempotencyRecord getIdempotency(String key) {\n        return idempotencyRecords.get(key);\n    }\n\n    public IdempotencyRecord putIfAbsentIdempotency(String key, IdempotencyRecord record) {\n        return idempotencyRecords.putIfAbsent(key, record);\n    }\n\n    public boolean verifySystemSolvency() {\n        Map<Currency, Long> netLedger = new ConcurrentHashMap<>();\n        for (Transaction tx : transactions.values()) {\n            for (LedgerEntry entry : tx.entries()) {\n                Currency c = entry.amount().currency();\n                long val = entry.type() == EntryType.DEBIT ? entry.amount().amount() : -entry.amount().amount();\n                netLedger.merge(c, val, Long::sum);\n            }\n        }\n        for (long net : netLedger.values()) {\n            if (net != 0) return false;\n        }\n        return true;\n    }\n\n    public long calculateAccountNetBalance(String accountId) {\n        Account acc = accounts.get(accountId);\n        if (acc == null) return 0;\n        List<LedgerEntry> entries = getEntriesForAccount(accountId);\n        long net = 0;\n        for (LedgerEntry entry : entries) {\n            if (entry.type() == EntryType.CREDIT) {\n                net += entry.amount().amount();\n            } else {\n                net -= entry.amount().amount();\n            }\n        }\n        return net;\n    }\n}\n"
