      "name": "GatewayRequest.java",
      "code": "import java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Objects;\n\npublic final class GatewayRequest {\n    private final String path;\n    private final HttpMethod method;\n    private final Map<String, List<String>> headers;\n    private final Map<String, String> queryParams;\n    private final String body;\n    private final String clientIp;\n    private final Instant timestamp;\n\n    public GatewayRequest(String path, HttpMethod method, Map<String, List<String>> headers, Map<String, String> queryParams, String body, String clientIp, Instant timestamp) {\n        this.path = Objects.requireNonNull(path, \"path cannot be null\");\n        this.method = Objects.requireNonNull(method, \"method cannot be null\");\n        this.headers = new HashMap<>();\n        if (headers != null) {\n            for (Map.Entry<String, List<String>> e : headers.entrySet()) {\n                this.headers.put(e.getKey().toLowerCase(), new ArrayList<>(e.getValue()));\n            }\n        }\n        this.queryParams = queryParams != null ? new HashMap<>(queryParams) : Collections.emptyMap();\n        this.body = body != null ? body : \"\";\n        this.clientIp = clientIp != null ? clientIp : \"127.0.0.1\";\n        this.timestamp = timestamp != null ? timestamp : Instant.now();\n    }\n\n    public static Builder builder() {\n        return new Builder();\n    }\n\n    public String path() { return path; }\n    public HttpMethod method() { return method; }\n    public Map<String, List<String>> headers() { return Collections.unmodifiableMap(headers); }\n    public Map<String, String> queryParams() { return Collections.unmodifiableMap(queryParams); }\n    public String body() { return body; }\n    public String clientIp() { return clientIp; }\n    public Instant timestamp() { return timestamp; }\n\n    public String header(String name) {\n        if (name == null) return null;\n        List<String> list = headers.get(name.toLowerCase());\n        return (list != null && !list.isEmpty()) ? list.get(0) : null;\n    }\n\n    public String headerOr(String name, String fallback) {\n        String val = header(name);\n        return val != null ? val : fallback;\n    }\n\n    public static final class Builder {\n        private String path = \"/\";\n        private HttpMethod method = HttpMethod.GET;\n        private final Map<String, List<String>> headers = new HashMap<>();\n        private final Map<String, String> queryParams = new HashMap<>();\n        private String body = \"\";\n        private String clientIp = \"127.0.0.1\";\n        private Instant timestamp = Instant.now();\n\n        public Builder path(String path) { this.path = path; return this; }\n        public Builder method(HttpMethod method) { this.method = method; return this; }\n        public Builder header(String name, String value) {\n            headers.computeIfAbsent(name.toLowerCase(), k -> new ArrayList<>()).add(value);\n            return this;\n        }\n        public Builder queryParam(String key, String value) { queryParams.put(key, value); return this; }\n        public Builder body(String body) { this.body = body; return this; }\n        public Builder clientIp(String clientIp) { this.clientIp = clientIp; return this; }\n        public Builder timestamp(Instant timestamp) { this.timestamp = timestamp; return this; }\n\n        public GatewayRequest build() {\n            return new GatewayRequest(path, method, headers, queryParams, body, clientIp, timestamp);\n        }\n    }\n}\n"
