      "name": "HeaderTransformFilter.java",
      "code": "import java.util.UUID;\n\npublic final class HeaderTransformFilter implements GatewayFilter {\n    @Override\n    public FilterType type() {\n        return FilterType.POST;\n    }\n\n    @Override\n    public int order() {\n        return 900;\n    }\n\n    @Override\n    public void filter(RequestContext ctx) {\n        String reqId = ctx.request().header(\"X-Request-Id\");\n        if (reqId == null || reqId.isBlank()) {\n            reqId = UUID.randomUUID().toString();\n        }\n        ctx.response().setHeader(\"X-Request-Id\", reqId);\n\n        long latency = System.currentTimeMillis() - ctx.startTimeMs();\n        ctx.response().setHeader(\"X-Gateway-Latency-Ms\", String.valueOf(latency));\n\n        ctx.response().setHeader(\"X-Content-Type-Options\", \"nosniff\");\n        ctx.response().setHeader(\"X-Frame-Options\", \"DENY\");\n    }\n}\n"
