      "name": "AuditLoggingFilter.java",
      "code": "import java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\npublic final class AuditLoggingFilter implements GatewayFilter {\n    private final List<AuditRecord> records = Collections.synchronizedList(new ArrayList<>());\n\n    @Override\n    public FilterType type() {\n        return FilterType.POST;\n    }\n\n    @Override\n    public int order() {\n        return 999;\n    }\n\n    @Override\n    public void filter(RequestContext ctx) {\n        String clientId = ctx.getAttribute(\"CLIENT_ID\", String.class);\n        long latency = System.currentTimeMillis() - ctx.startTimeMs();\n        AuditRecord record = new AuditRecord(\n                Instant.now(),\n                ctx.request().clientIp(),\n                clientId != null ? clientId : \"anonymous\",\n                ctx.request().method(),\n                ctx.request().path(),\n                ctx.response().statusCode(),\n                latency\n        );\n        records.add(record);\n    }\n\n    public List<AuditRecord> records() {\n        synchronized (records) {\n            return new ArrayList<>(records);\n        }\n    }\n}\n"
