      "name": "RouteResolutionFilter.java",
      "code": "public final class RouteResolutionFilter implements GatewayFilter {\n    private final RoutingTable routingTable;\n\n    public RouteResolutionFilter(RoutingTable routingTable) {\n        this.routingTable = routingTable;\n    }\n\n    @Override\n    public FilterType type() {\n        return FilterType.PRE;\n    }\n\n    @Override\n    public int order() {\n        return 10;\n    }\n\n    @Override\n    public void filter(RequestContext ctx) {\n        Route route = routingTable.findRoute(ctx.request().path());\n        if (route == null) {\n            ctx.terminate(404, \"{\\\"error\\\": \\\"Not Found\\\", \\\"message\\\": \\\"No matching route for path \" + ctx.request().path() + \"\\\"}\");\n            return;\n        }\n        ctx.setAttribute(\"MATCHED_ROUTE\", route);\n    }\n}\n"
